const inputs = $input.all().map(i => i.json || {});
const raw = inputs[0] || {};
const env = $env || {};

// Support both direct fields and body wrapper
const merged = (raw && raw.body && typeof raw.body === 'object') ? { ...raw.body, ...raw } : raw;

// Campaign config may come from upstream node (Load Campaign) or payload
const campaign = merged.campaign || {};

const runConfig = {
  run_id: `prospect-run-${Date.now()}`,
  started_at: new Date().toISOString(),
  campaign_id: merged.campaign_id || campaign.id || env.DEFAULT_CAMPAIGN_ID || 'agentyx',
  campaign: campaign,
  linkedin_query: campaign.icp?.linkedin_query || merged.linkedin_query || env.LINKEDIN_SEARCH_QUERY || 'operations manager ai automation latam',
  leads_per_run: Number(campaign.icp?.leads_per_run || merged.leads_per_run || env.LEADS_PER_RUN || 25),
  fit_threshold: Number(campaign.icp?.fit_threshold || merged.fit_threshold || env.LEAD_FIT_THRESHOLD || 70),
  dry_run: Boolean(merged.dry_run || env.PROSPECTOR_DRY_RUN === 'true'),
  test_leads: Array.isArray(merged.test_leads) ? merged.test_leads : null,
  tenant: campaign.tenant || merged.tenant || env.TENANT_SLUG || 'levinnovation',
  product_name: campaign.product?.name || '',
  product_description: campaign.product?.description || '',
};
return [{ json: runConfig }];

const cfg = $('Initialize Run v2').first().json;
let rawLeads = [];

if (Array.isArray(cfg.test_leads) && cfg.test_leads.length > 0) {
  rawLeads = cfg.test_leads;
} else {
  const payload = $input.first().json || {};
  rawLeads = payload.data || payload.results || payload.items || payload.profiles || [];
}

const normalized = (Array.isArray(rawLeads) ? rawLeads : []).map((lead, index) => {
  const fullName = lead.full_name || lead.contact_name || [lead.first_name, lead.last_name].filter(Boolean).join(' ') || lead.name || '';
  const company = lead.company_name || lead.company || lead.current_company || '';
  const role = lead.title || lead.headline || lead.position || '';
  const email = String(lead.email || lead.work_email || '').toLowerCase().trim();
  const linkedin = lead.profile_url || lead.linkedin_url || lead.url || '';
  const location = lead.location || lead.geo || '';
  const companyWebsite = lead.company_website || lead.website || '';
  const summary = lead.summary || lead.about || role;
  return {
    run_id: cfg.run_id,
    lead_id: `${cfg.run_id}-${index + 1}`,
    campaign_id: cfg.campaign_id,
    product_name: cfg.product_name,
    full_name: fullName,
    company,
    role,
    email,
    linkedin_url: linkedin,
    company_website: companyWebsite,
    location,
    summary,
    fit_threshold: cfg.fit_threshold,
    dry_run: cfg.dry_run,
    source_payload: lead,
    email_status: email ? 'found_in_source' : 'missing',
    email_source: email ? 'linkedin_source' : 'unknown',
  };
}).filter((l) => l.full_name && (l.linkedin_url || l.email));

return normalized.map((lead) => ({ json: lead }));

const lead = $('Split In Batches').item.json;
